import React, { useEffect, useRef, useState } from 'react';
import * as THREE from 'three';
import { GLTFLoader } from 'three/examples/jsm/loaders/GLTFLoader';
import { OrbitControls } from 'three/examples/jsm/controls/OrbitControls';

const GlbTest = () => {
  const canvasRef = useRef(null);
  const rendererRef = useRef(null);
  const sceneRef = useRef(null);
  const cameraRef = useRef(null);
  const mixerRef = useRef(null);
  const animationActionRef = useRef(null);
  const clockRef = useRef(new THREE.Clock());
  const [isPlaying, setIsPlaying] = useState(false);
  const [loadingStatus, setLoadingStatus] = useState('Loading...');
  const [error, setError] = useState(null);

  useEffect(() => {
    if (!canvasRef.current) return;

    const initThreeJS = () => {
      sceneRef.current = new THREE.Scene();
      cameraRef.current = new THREE.PerspectiveCamera(75, 1, 0.1, 1000);

      rendererRef.current = new THREE.WebGLRenderer({ antialias: true, canvas: canvasRef.current });
      rendererRef.current.setSize(400, 400);
      rendererRef.current.setClearColor(0xcccccc);

      const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
      sceneRef.current.add(ambientLight);

      const directionalLight = new THREE.DirectionalLight(0xffffff, 0.8);
      directionalLight.position.set(2, 2, 2);
      sceneRef.current.add(directionalLight);

      cameraRef.current.position.z = 5;

      const controls = new OrbitControls(cameraRef.current, rendererRef.current.domElement);
      controls.update();
    };

    const loadModel = () => {
      const loader = new GLTFLoader();
      const modelPath = '/static/models/body__animated_test_something.glb';

      loader.load(
        modelPath, 
        (gltf) => {
          const model = gltf.scene;
          sceneRef.current.add(model);

          mixerRef.current = new THREE.AnimationMixer(model);

          if (gltf.animations.length > 0) {
            animationActionRef.current = mixerRef.current.clipAction(gltf.animations[0]);
            animationActionRef.current.setLoop(THREE.LoopRepeat);
            animationActionRef.current.clampWhenFinished = true;
          }

          const box = new THREE.Box3().setFromObject(model);
          const center = box.getCenter(new THREE.Vector3());
          const size = box.getSize(new THREE.Vector3());

          // Adjust camera position based on model size
          const maxDim = Math.max(size.x, size.y, size.z);
          const fov = cameraRef.current.fov * (Math.PI / 180);
          let cameraZ = Math.abs(maxDim / 2 / Math.tan(fov / 2));
          cameraZ *= 1.5; // Zoom out a bit

          cameraRef.current.position.set(center.x, center.y, center.z + cameraZ);
          cameraRef.current.lookAt(center);
          cameraRef.current.updateProjectionMatrix();

          setLoadingStatus('Loaded Successfully');
        },
        (xhr) => {
          if (xhr.lengthComputable) {
            const percentComplete = xhr.loaded / xhr.total * 100;
            setLoadingStatus(`${Math.round(percentComplete)}% loaded`);
          }
        },
        (error) => {
          console.error('Error loading GLB file:', error);
          setError(`Failed to load model: ${error.message}`);
          setLoadingStatus('Load Failed');
        }
      );
    };

    initThreeJS();
    loadModel();

    const animate = () => {
      requestAnimationFrame(animate);

      if (mixerRef.current) {
        const delta = clockRef.current.getDelta();
        mixerRef.current.update(delta);
      }

      if (rendererRef.current && sceneRef.current && cameraRef.current) {
        rendererRef.current.render(sceneRef.current, cameraRef.current);
      }
    };

    animate();

    return () => {
      if (rendererRef.current) {
        rendererRef.current.dispose();
      }
    };
  }, []);

  const toggleAnimation = () => {
    if (animationActionRef.current) {
      if (isPlaying) {
        animationActionRef.current.stop();
      } else {
        animationActionRef.current.play();
      }
      setIsPlaying(!isPlaying);
    }
  };

  return (
    <div>
      <canvas ref={canvasRef} style={{ width: '400px', height: '400px', border: '1px solid black' }} />
      <div style={{ marginTop: '10px' }}>
        <p>Status: {loadingStatus}</p>
        {error && <p style={{ color: 'red' }}>{error}</p>}
      </div>
      <button 
        onClick={toggleAnimation}
        disabled={loadingStatus !== 'Loaded Successfully'}
        style={{
          marginTop: '10px',
          padding: '5px 10px',
          fontSize: '14px'
        }}
      >
        {isPlaying ? 'Pause Animation' : 'Start Animation'}
      </button>
    </div>
  );
};

export default GlbTest;
